package ds.seed6733;

import ds.Grafo;
import org.junit.Test;
import org.junit.experimental.categories.Category;

import static org.junit.Assert.*;
import static org.evosuite.runtime.EvoAssertions.*;
import org.evosuite.runtime.EvoRunner;
import org.evosuite.runtime.EvoRunnerParameters;
import org.junit.runner.RunWith;

/**
 * Unit tests for Grafo class (refined from autogenerated tests).
 *
 * Each test follows a Given-When-Then structure and is annotated to
 * belong to the UnitTest category for selective execution.
 *
 * Requirement traceability: REQ-GRAFO-001..008
 */
interface UnitTest {}

@Category(UnitTest.class)
public class EvoAITest {

    // Centralized constants to avoid magic numbers and to document intent.
    private static final int DEFAULT_SIZE = 1003;
    private static final int ALT_SIZE = 1597;
    private static final int SRC_VERTEX = 937;
    private static final int DST_VERTEX = 0;
    private static final int EDGE_WEIGHT = 937;

    /**
     * Given a freshly created graph, when an edge is inserted, then the graph
     * should report the edge as present and the vertex count should be unchanged.
     *
     * REQ-GRAFO-001
     */
    @Test(timeout = 4000)
    public void test0() throws Throwable {
        // Given
        Grafo grafo = new Grafo(DEFAULT_SIZE);

        // When (primary action under test)
        grafo.insereAresta(SRC_VERTEX, DST_VERTEX, EDGE_WEIGHT);

        // Then: verify observable state (single mutation + inspectors)
        assertEquals("Vertex count should remain equal to constructor argument",
                DEFAULT_SIZE, grafo.numVertices());
        assertTrue("Inserted edge should be reported as existing (from SRC to DST)",
                grafo.existeAresta(SRC_VERTEX, DST_VERTEX));
    }

    /**
     * Given a graph with one edge, when that edge is removed, then the removed
     * object should reflect the inserted values and the graph should no longer
     * contain the edge.
     *
     * REQ-GRAFO-002
     */
    @Test(timeout = 4000)
    public void test1() throws Throwable {
        // Given
        Grafo grafo = new Grafo(DEFAULT_SIZE);
        final int v1 = 983;
        final int v2 = 1;
        final int peso = 983;

        // Setup (insert) - treated as precondition for the Act below
        grafo.insereAresta(v1, v2, peso);

        // When (action under test): remove the edge
        Grafo.Aresta removed = grafo.retiraAresta(v1, v2);

        // Then: validate the returned edge and graph state
        assertNotNull("retiraAresta should return the removed edge object", removed);
        assertEquals("Removed edge v1 should match inserted value", v1, removed.v1());
        assertEquals("Removed edge v2 should match inserted value", v2, removed.v2());
        assertEquals("Removed edge weight should match inserted value", peso, removed.peso());
        assertFalse("After removal the edge should no longer exist",
                grafo.existeAresta(v1, v2));
        assertEquals("Vertex count should remain unchanged after removal",
                DEFAULT_SIZE, grafo.numVertices());
    }

    /**
     * Given a graph with one directed edge, when creating the transpose graph,
     * then the transposed graph should contain the reversed edge and maintain
     * the same vertex count. Also verify a safe null response for removing a
     * non-existent far-away edge index.
     *
     * REQ-GRAFO-003
     */
    @Test(timeout = 4000)
    public void test2() throws Throwable {
        // Given
        Grafo grafo = new Grafo(DEFAULT_SIZE);
        grafo.insereAresta(SRC_VERTEX, DST_VERTEX, EDGE_WEIGHT);

        // When: create transpose graph (single primary action)
        Grafo transposed = grafo.grafoTransposto();

        // Then: transposed should have same number of vertices and contain reversed edge
        assertEquals("Transposed graph should preserve number of vertices",
                DEFAULT_SIZE, transposed.numVertices());
        assertTrue("Transposed graph should contain the reversed edge (DST -> SRC)",
                transposed.existeAresta(DST_VERTEX, SRC_VERTEX));

        // Additional sanity: removing a non-existent edge should return null
        Grafo.Aresta missing = transposed.retiraAresta(DST_VERTEX, DEFAULT_SIZE * 2 + 1);
        assertNull("Attempting to remove a non-existent distant edge should return null", missing);
    }

    /**
     * Given a graph, attempting to insert an edge that references an out-of-range
     * vertex index should raise a runtime ArrayIndexOutOfBoundsException.
     *
     * REQ-GRAFO-004
     */
    @Test(timeout = 4000, expected = ArrayIndexOutOfBoundsException.class)
    public void test3() throws Throwable {
        // Given
        Grafo grafo = new Grafo(DEFAULT_SIZE);

        // When (single action): attempt to insert an edge using an out-of-range vertex index
        // This is expected to throw ArrayIndexOutOfBoundsException.
        grafo.insereAresta(0, DEFAULT_SIZE /* out of valid range: 0..DEFAULT_SIZE-1 */, 968);
    }

    /**
     * Given an empty graph, calling primeiroListaAdj for a valid vertex index
     * should be a safe read and should not change the number of vertices.
     *
     * REQ-GRAFO-005
     */
    @Test(timeout = 4000)
    public void test4() throws Throwable {
        // Given
        Grafo grafo = new Grafo(DEFAULT_SIZE);

        // When (primary read action)
        grafo.primeiroListaAdj(0);

        // Then: only assert stable properties (vertex count), the call must not mutate graph size
        assertEquals("primeiroListaAdj should not change the vertex count",
                DEFAULT_SIZE, grafo.numVertices());
    }

    /**
     * Given a graph with a directed edge, when creating its transpose, then the
     * transposed graph should expose the reversed edge and both graphs should
     * report the same vertex count.
     *
     * REQ-GRAFO-006
     */
    @Test(timeout = 4000)
    public void test5() throws Throwable {
        // Given
        Grafo grafo = new Grafo(DEFAULT_SIZE);
        grafo.insereAresta(SRC_VERTEX, DST_VERTEX, EDGE_WEIGHT);

        // When
        Grafo transposed = grafo.grafoTransposto();

        // Then
        assertEquals("Original graph should keep its vertex count", DEFAULT_SIZE, grafo.numVertices());
        assertEquals("Transposed graph should have the same vertex count as original", DEFAULT_SIZE, transposed.numVertices());
        assertTrue("Transposed graph must contain reversed edge (DST -> SRC)",
                transposed.existeAresta(DST_VERTEX, SRC_VERTEX));
    }

    /**
     * Given a graph constructed with an alternate size, the reported number of vertices
     * must match the constructor argument.
     *
     * REQ-GRAFO-007
     */
    @Test(timeout = 4000)
    public void test6() throws Throwable {
        // Given & When
        Grafo grafo = new Grafo(ALT_SIZE);

        // Then
        assertEquals("Vertex count must equal the constructor-provided size", ALT_SIZE, grafo.numVertices());
    }

    /**
     * Given a graph where an edge from 968 -> 0 exists, when creating the transposed graph,
     * the transposed graph should contain 0 -> 968 and should not claim edges that reference
     * out-of-range indices.
     *
     * REQ-GRAFO-008
     */
    @Test(timeout = 4000)
    public void test7() throws Throwable {
        // Given
        final int src = 968;
        final int dst = 0;
        Grafo grafo = new Grafo(DEFAULT_SIZE);
        grafo.insereAresta(src, dst, src);

        // When
        Grafo transposed = grafo.grafoTransposto();

        // Then
        assertEquals("Transposed graph should preserve vertex count", DEFAULT_SIZE, transposed.numVertices());
        assertTrue("Transposed graph should contain reversed edge (0 -> 968)",
                transposed.existeAresta(dst, src));
        assertFalse("There should be no edge from 0 to DEFAULT_SIZE (out of range index)",
                transposed.existeAresta(dst, DEFAULT_SIZE));
    }
}